import{_ as a,o as e,c as s,a5 as i}from"./chunks/framework.DJo0M80U.js";const h=JSON.parse('{"title":"HJ77 火车进站","description":"中等 通过率：43.39% 时间限制：1秒 空间限制：32M 知识点 栈 描述 给定一个正整数N代表火车数量，0\\\\<N\\\\<10，接下来输入火车入站的序列，一共N辆火车，每辆火车以数字1 9编号，火车站只有一个方向进出，同时停靠在火车站的列车中，只有后进站的出站了，先进站的才能出站。","frontmatter":{"title":"HJ77 火车进站","date":"2026-08-11T00:00:00.000Z","categories":["前端面试与实战"],"tags":["前端面试","算法","求职","教程","OneNote","算法训练"],"description":"中等 通过率：43.39% 时间限制：1秒 空间限制：32M 知识点 栈 描述 给定一个正整数N代表火车数量，0\\\\<N\\\\<10，接下来输入火车入站的序列，一共N辆火车，每辆火车以数字1 9编号，火车站只有一个方向进出，同时停靠在火车站的列车中，只有后进站的出站了，先进站的才能出站。","sidebarWeight":23,"lastUpdated":false,"feed":false,"source":"onenote","sourceNote":"OneNote/a-吊打面试官/算法题/动态规划【中等】/HJ77 火车进站.md"},"headers":[],"relativePath":"posts/前端面试与实战/03-算法训练/动态规划【中等】/HJ77 火车进站.md","filePath":"posts/前端面试与实战/03-算法训练/动态规划【中等】/HJ77 火车进站.md"}'),o={name:"posts/前端面试与实战/03-算法训练/动态规划【中等】/HJ77 火车进站.md"};function n(r,t,l,c,d,_){return e(),s("div",null,[...t[0]||(t[0]=[i('<div><h1 id="hj77-火车进站" tabindex="-1">HJ77 火车进站 <a class="header-anchor" href="#hj77-火车进站" aria-label="Permalink to &quot;HJ77 火车进站&quot;">​</a></h1><blockquote><p>本节目标：理解“HJ77 火车进站”的核心思路，并能把它用于实际开发或面试表达。 中等 通过率：43.39% 时间限制：1秒 空间限制：32M 知识点==栈== <strong>描述</strong> 给定一个正整数N代表火车数量，0&lt;N&lt;10，接下来输入火车入站的序列，一共N辆火车，每辆火车以数字1-9编号，火车站只有一个方向进出，同时停靠在火车站的列车中，只有后进站的出站了，先进站的才能出站。 要求输出所有火车出站的方案，以字典序排序输出。 数据范围：1≤<em>n</em>≤10 进阶：时间复杂度：<em>O</em>(<em>n</em>!) ，空间复杂度：<em>O</em>(<em>n</em>) <strong>输入描述：</strong> 第一行输入一个正整数N（0 &lt; N &lt;= 10），第二行包括N个正整数，范围为1到10。 <strong>输出描述：</strong> 输出以字典序从小到大排序的火车出站序列号，每个编号以空格隔开，每个输出序列换行，具体见sample。 <strong>示例1</strong> 输入： 31 2 3 ==复制== 输出： 1 2 31 3 22 1 32 3 13 2 1 ==复制== 说明： 第一种方案：1进、1出、2进、2出、3进、3出第二种方案：1进、1出、2进、3进、3出、2出第三种方案：1进、2进、2出、1出、3进、3出第四种方案：1进、2进、2出、3进、3出、1出第五种方案：1进、2进、3进、3出、2出、1出请注意，[3,1,2]这个序列是不可能实现的。</p></blockquote><p>这个问题可以通过递归方法来解决，核心思想是尝试所有可能的出站序列，并利用栈来模拟火车的进站和出站过程。对于每辆火车，都有两种选择：进站或者出站（如果栈非空）。</p><p>具体实现步骤如下：</p><ol><li>初始化两个栈，一个用于模拟火车进站（in_stack），一个用于存储当前的出站序列（out_stack）。</li><li>递归地尝试每辆火车的进站和出站操作。</li></ol><ul><li>对于进站操作，将火车压入in_stack，然后递归处理下一辆火车。</li><li>对于出站操作，将in_stack的顶部元素弹出，加入到out_stack中，然后递归处理下一辆火车。</li></ul><ol start="3"><li>当所有火车都已处理完毕，如果in_stack为空，则将当前的出站序列（out_stack）加入到结果集中。</li><li>最后，将所有可能的出站序列按字典序排序，并输出。</li></ol><p>代码示例：</p><h1 id="定义一个深度优先搜索的递归函数-用于探索所有可能的火车出站顺序" tabindex="-1">定义一个深度优先搜索的递归函数，用于探索所有可能的火车出站顺序 <a class="header-anchor" href="#定义一个深度优先搜索的递归函数-用于探索所有可能的火车出站顺序" aria-label="Permalink to &quot;定义一个深度优先搜索的递归函数，用于探索所有可能的火车出站顺序&quot;">​</a></h1><p>def dfs(in_stack, out_stack, in_list, result):</p><h1 id="如果没有火车需要进站-且站内也没有火车-记录当前的出站序列" tabindex="-1">如果没有火车需要进站，且站内也没有火车，记录当前的出站序列 <a class="header-anchor" href="#如果没有火车需要进站-且站内也没有火车-记录当前的出站序列" aria-label="Permalink to &quot;如果没有火车需要进站，且站内也没有火车，记录当前的出站序列&quot;">​</a></h1><p>if not in_list and not in_stack: result.append(&#39; &#39;.join(out_stack)) # 将当前出站序列添加到结果列表中 return</p><h1 id="如果站内有火车-尝试将最后进站的火车出站" tabindex="-1">如果站内有火车，尝试将最后进站的火车出站 <a class="header-anchor" href="#如果站内有火车-尝试将最后进站的火车出站" aria-label="Permalink to &quot;如果站内有火车，尝试将最后进站的火车出站&quot;">​</a></h1><p>if in_stack: dfs(in_stack[:-1], out_stack + [in_stack[-1]], in_list, result) # 出站操作，递归调用dfs</p><h1 id="如果还有火车未进站-尝试让下一辆火车进站" tabindex="-1">如果还有火车未进站，尝试让下一辆火车进站 <a class="header-anchor" href="#如果还有火车未进站-尝试让下一辆火车进站" aria-label="Permalink to &quot;如果还有火车未进站，尝试让下一辆火车进站&quot;">​</a></h1><p>if in_list: dfs(in_stack + [in_list[0]], out_stack, in_list[1:], result) # 进站操作，递归调用dfs</p><h1 id="主函数-处理输入和打印所有合法的出站顺序" tabindex="-1">主函数，处理输入和打印所有合法的出站顺序 <a class="header-anchor" href="#主函数-处理输入和打印所有合法的出站顺序" aria-label="Permalink to &quot;主函数，处理输入和打印所有合法的出站顺序&quot;">​</a></h1><p>def train_out(N, trains): result = [] # 初始化一个空列表，用于存储所有可能的出站顺序</p><h1 id="调用dfs函数开始递归搜索-初始时站内无火车-in-stack为空-还未有火车出站-out-stack为空-待处理的火车序列为trains" tabindex="-1">调用dfs函数开始递归搜索，初始时站内无火车（in_stack为空），还未有火车出站（out_stack为空），待处理的火车序列为trains <a class="header-anchor" href="#调用dfs函数开始递归搜索-初始时站内无火车-in-stack为空-还未有火车出站-out-stack为空-待处理的火车序列为trains" aria-label="Permalink to &quot;调用dfs函数开始递归搜索，初始时站内无火车（in_stack为空），还未有火车出站（out_stack为空），待处理的火车序列为trains&quot;">​</a></h1><p>dfs([], [], trains, result)</p><h1 id="对找到的所有出站顺序进行排序-然后依次打印出来" tabindex="-1">对找到的所有出站顺序进行排序，然后依次打印出来 <a class="header-anchor" href="#对找到的所有出站顺序进行排序-然后依次打印出来" aria-label="Permalink to &quot;对找到的所有出站顺序进行排序，然后依次打印出来&quot;">​</a></h1><p>for seq in sorted(result): print(seq)</p><h1 id="读取输入数据" tabindex="-1">读取输入数据 <a class="header-anchor" href="#读取输入数据" aria-label="Permalink to &quot;读取输入数据&quot;">​</a></h1><p>N = int(input().strip()) # 火车的数量 trains = input().strip().split() # 火车进站的序列</p><h1 id="调用train-out函数处理输入并打印结果" tabindex="-1">调用train_out函数处理输入并打印结果 <a class="header-anchor" href="#调用train-out函数处理输入并打印结果" aria-label="Permalink to &quot;调用train_out函数处理输入并打印结果&quot;">​</a></h1><p>train_out(N, trains)</p><p>这里<code>dfs</code>函数是递归的核心，它尝试所有可能的出站序列。<code>in_stack</code>代表当前站内的火车，<code>out_stack</code>代表已经出站的火车序列，<code>in_list</code>代表还未进站的火车。当<code>in_list</code>和<code>in_stack</code>都为空时，意味着所有火车都已经出站，此时的<code>out_stack</code>即为一种可能的出站序列。</p><p>需要注意的是，由于火车出站的顺序是有限制的（只有最后进站的火车可以出站），所以并不是所有的排列都是可能的，上述算法正是通过模拟进出站的过程来确保生成的出站序列是合法的。</p></div>',1)])])}const p=a(o,[["render",n]]);export{h as __pageData,p as default};
